// Writes runtimes/engine/licenses/accesskit/crates-<target>.md: the Rust crates
// compiled into the pinned accesskit-c static library for each prebuilt
// target, with their license texts. The release archive carries no notices
// for them. Needs cargo and network access to GitHub and crates.io.
//
//   node .github/scripts/accesskit-notices.mjs          regenerate
//   node .github/scripts/accesskit-notices.mjs --check  fail if out of date
import { execFileSync } from 'node:child_process';
import {
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../../', import.meta.url));
const engine = join(root, 'runtimes/engine');
const pins = readFileSync(
  join(engine, 'cmake/SoundorDependencies.cmake'),
  'utf8',
);
const version = pins.match(/SOUNDOR_ACCESSKIT_VERSION "([^"]+)"/)[1];
// The prebuilt targets that link AccessKit (Apple uses Soundor's own bridges).
const targets = {
  'linux-x64': 'x86_64-unknown-linux-gnu',
  'windows-x64': 'x86_64-pc-windows-msvc',
};
const noticeName = /^(licen[cs]e|copying|notice|unlicense|copyright)/i;

const work = mkdtempSync(join(tmpdir(), 'accesskit-notices-'));
let stale = false;
try {
  execFileSync(
    'sh',
    [
      '-c',
      `curl -sfL https://github.com/AccessKit/accesskit-c/archive/refs/tags/${version}.tar.gz | tar xz -C "${work}" --strip-components=1`,
    ],
    { stdio: 'inherit' },
  );
  const project = readdirSync(work);
  if (!project.includes('Cargo.lock'))
    throw new Error(`accesskit-c ${version} has no Cargo.lock`);
  const own = ['LICENSE-MIT', 'LICENSE-APACHE', 'LICENSE.chromium'];
  for (const [target, triple] of Object.entries(targets)) {
    const metadata = JSON.parse(
      execFileSync(
        'cargo',
        [
          'metadata',
          '--locked',
          '--format-version',
          '1',
          '--filter-platform',
          triple,
        ],
        { cwd: work, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 },
      ),
    );
    const packages = new Map(metadata.packages.map((p) => [p.id, p]));
    const nodes = new Map(metadata.resolve.nodes.map((n) => [n.id, n]));
    const rootId = metadata.packages.find((p) => p.name === 'accesskit-c').id;
    // What is linked: normal dependencies, without build-time crates (proc
    // macros run in the compiler, build scripts before it).
    const linked = new Set();
    const pending = [rootId];
    while (pending.length) {
      const id = pending.pop();
      if (linked.has(id)) continue;
      linked.add(id);
      for (const dep of nodes.get(id).deps) {
        const crate = packages.get(dep.pkg);
        if (!dep.dep_kinds.some((kind) => kind.kind === null)) continue;
        if (crate.targets.some((t) => t.kind.includes('proc-macro'))) continue;
        pending.push(dep.pkg);
      }
    }
    const crates = [...linked]
      .map((id) => packages.get(id))
      .filter((p) => p.name !== 'accesskit-c')
      .sort(
        (a, b) =>
          a.name.localeCompare(b.name) || a.version.localeCompare(b.version),
      );
    // Identical texts once, with every crate they come from.
    const texts = new Map();
    const rows = [];
    for (const crate of crates) {
      const directory = dirname(crate.manifest_path);
      let files = readdirSync(directory)
        .filter((name) => noticeName.test(name))
        .sort();
      let from = directory;
      // AccessKit's own crates ship without license files: accesskit-c's
      // (the same project, the same terms) apply.
      if (files.length === 0 && crate.name.startsWith('accesskit')) {
        files = own;
        from = work;
      }
      if (files.length === 0)
        throw new Error(`${crate.name} ${crate.version} has no license file`);
      rows.push(
        `| ${crate.name} | ${crate.version} | ${crate.license ?? 'see text'} |`,
      );
      for (const file of files) {
        const text = readFileSync(join(from, file), 'utf8')
          .replace(/\r\n/g, '\n')
          .trimEnd();
        const users = texts.get(text) ?? [];
        users.push(`${crate.name} ${crate.version} (${file})`);
        texts.set(text, users);
      }
    }
    const sections = [...texts.entries()].map(
      ([text, users]) =>
        `### ${users.join(', ')}\n\n\`\`\`text\n${text}\n\`\`\``,
    );
    const output = `# Rust crates in AccessKit (${target})

The accesskit-c ${version} static library Soundor links on ${target} compiles
these crates (its Cargo.lock, resolved for ${triple}; build-time crates
excluded), and the Rust standard library (../rust). AccessKit's own license
texts are next to this file.

Generated by .github/scripts/accesskit-notices.mjs; do not edit.

| Crate | Version | License |
| ----- | ------- | ------- |
${rows.join('\n')}

## License texts

${sections.join('\n\n')}
`;
    const path = join(engine, `licenses/accesskit/crates-${target}.md`);
    if (process.argv.includes('--check')) {
      let current = '';
      try {
        current = readFileSync(path, 'utf8');
      } catch {}
      if (current !== output) {
        console.error(`${path} is out of date`);
        stale = true;
      }
    } else {
      writeFileSync(path, output);
      console.log(`${path}: ${crates.length} crates`);
    }
  }
} finally {
  rmSync(work, { recursive: true, force: true });
}
if (stale) process.exit(1);
